// Get the first item coming from the Webhook
const request = items[0].json;
const body = request.body || {};

const seeds = (body.seeds || body.topic || '')
  .split(',')
  .map(k => k.trim())
  .filter(Boolean);

return [
  {
    json: {
      trigger_id: body.trigger_id,
      topic: body.topic || seeds[0] || '',
      seeds,
      country_code: body.location || body.country_code || 'US',
      language_code: body.language_code || 'en'
    }
  }
];

const input = items[0].json;
const seeds = (input.seeds && input.seeds.length > 0)
  ? input.seeds
  : [input.topic].filter(Boolean);

const letters = 'abcdefghijklmnopqrstuvwxyz'.split('');
const modifiers = ['how to', 'best', 'vs', 'for', 'near me'];
const queries = [];

for (const seed of seeds) {
  queries.push(seed);
  for (const l of letters) {
    queries.push(`${seed} ${l}`);
  }
  for (const m of modifiers) {
    queries.push(`${seed} ${m}`);
  }
}

return queries.map(q => ({
  json: {
    query: q,
    country_code: input.country_code,
    language_code: input.language_code
  }
}));

const out = [];
for (const item of items) {
  const raw = item.json.data;
  let res;
  if (typeof raw === 'string') {
    res = JSON.parse(raw);
  } else {
    res = raw || [];
  }
  const suggestions = (Array.isArray(res) && Array.isArray(res[1])) ? res[1] : [];
  for (const s of suggestions) {
    out.push({
      json: {
        keyword: s
      }
    });
  }
}
return out;

const allItems = $items('Flatten Suggestions');
const map = {};
for (const i of allItems) {
  const kw = (i.json.keyword || '').trim();
  if (!kw) continue;
  const key = kw.toLowerCase();
  map[key] = kw;
}
return Object.values(map).map(kw => ({
  json: { keyword: kw }
}));

let parsed;
try {
  parsed = JSON.parse($json.text);
} catch (e) {
  parsed = {
    keyword: $json.keyword || 'Keyword',
    cluster: 'General',
    search_intent: 'Informational',
    priority: 3
  };
}
const countryCode = $('Webhook').first().json.body.location || $('Webhook').first().json.body.country_code || 'IN';
const now = new Date();
const localDate = `${String(now.getDate()).padStart(2, '0')}/${String(now.getMonth() + 1).padStart(2, '0')}/${now.getFullYear()}, ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}:${String(now.getSeconds()).padStart(2, '0')}`;

return {
  keyword: parsed.keyword,
  cluster: parsed.cluster,
  search_intent: parsed.search_intent,
  priority: parsed.priority,
  get_time: localDate
};
